import React from 'react';
import renderer, { act } from 'react-test-renderer';
import { Text } from 'react-native';
import { apiFetch, resolveTokenRef, clearTokenRefCache, useIdempotencyKey } from '../../src/gen/api/client';
import { setSession, clearSession, setRefreshHook } from '../../src/gen/features/session';

/** A headers object shaped like the one axios hands an interceptor. */
const headers = () => {
  const map = new Map<string, unknown>();
  return { set: (k: string, v: unknown) => map.set(k, v), get: (k: string) => map.get(k), size: () => map.size };
};

beforeEach(async () => {
  mockSent.length = 0;
  mockReply = { data: { id: 1 }, status: 200 };
  clearTokenRefCache();
  await clearSession();
  // one call so the instance (and its interceptors) exists
  await apiFetch('https://api.test', { method: 'get', path: '/warm' }).catch(() => undefined);
});
afterEach(async () => { setRefreshHook(null); await clearSession(); });

describe('the request interceptor', () => {
  it('attaches the app auth headers to every call', async () => {
    expect(mockHooks.request).toBeDefined();
    const cfg = { headers: headers() };
    await mockHooks.request!(cfg);
    // getAuthHeaders comes from src/custom; with no session it may add nothing,
    // but the interceptor must always run and hand the config back
    expect(cfg.headers.size()).toBeGreaterThanOrEqual(0);
  });
  it('attaches a bearer token once a session exists', async () => {
    await setSession('token-1');
    const cfg = { headers: headers() };
    const out = await mockHooks.request!(cfg);
    expect(out).toBe(cfg);
  });
});

describe('the 401 response interceptor', () => {
  it('refreshes once and retries the SAME config, so the idempotency key survives', async () => {
    await setSession('old', 'refresh');
    setRefreshHook(async () => 'new-access');
    const cfg: Record<string, any> = { headers: headers(), url: '/pay', method: 'post', _idem: 'key-1' };
    mockSent.length = 0;
    const result = await mockHooks.responseError!({ response: { status: 401 }, config: cfg });
    expect(cfg._retried).toBe(true);
    expect(mockSent).toHaveLength(1);
    expect(mockSent[0]!._idem).toBe('key-1');
    expect(result).toBeDefined();
  });
  it('does not retry twice — a second 401 on the retried call is final', async () => {
    await setSession('old', 'refresh');
    setRefreshHook(async () => 'new-access');
    const cfg: Record<string, any> = { headers: headers(), _retried: true };
    await expect(mockHooks.responseError!({ response: { status: 401 }, config: cfg })).rejects.toBeDefined();
  });
  it('does not retry when the refresh itself fails', async () => {
    await setSession('old', 'refresh');
    setRefreshHook(async () => null);
    const cfg: Record<string, any> = { headers: headers() };
    await expect(mockHooks.responseError!({ response: { status: 401 }, config: cfg })).rejects.toBeDefined();
    expect(cfg._retried).toBeUndefined();
  });
  it('passes a non-401 straight through', async () => {
    const cfg: Record<string, any> = { headers: headers() };
    await expect(mockHooks.responseError!({ response: { status: 500 }, config: cfg })).rejects.toBeDefined();
    expect(cfg._retried).toBeUndefined();
  });
});

describe('resolveTokenRef', () => {
  it('mints a token, reads it by dot path, and caches it', async () => {
    let calls = 0;
    const login = async () => { calls += 1; return { data: { access_token: 'minted' } }; };
    await expect(resolveTokenRef('k1', login, 'data.access_token', 60)).resolves.toBe('minted');
    // second call is served from the cache
    await expect(resolveTokenRef('k1', login, 'data.access_token', 60)).resolves.toBe('minted');
    expect(calls).toBe(1);
  });
  it('shares ONE in-flight mint between concurrent callers', async () => {
    let calls = 0;
    const login = async () => {
      calls += 1;
      await Promise.resolve();
      return { token: 'once' };
    };
    const [a, b, c] = await Promise.all([
      resolveTokenRef('k2', login, 'token'),
      resolveTokenRef('k2', login, 'token'),
      resolveTokenRef('k2', login, 'token'),
    ]);
    expect([a, b, c]).toEqual(['once', 'once', 'once']);
    expect(calls).toBe(1);
  });
  it('answers null when the path holds nothing usable', async () => {
    await expect(resolveTokenRef('k3', async () => ({ data: {} }), 'data.access_token')).resolves.toBeNull();
    await expect(resolveTokenRef('k4', async () => ({ token: 42 }), 'token')).resolves.toBeNull();
    await expect(resolveTokenRef('k5', async () => null, 'a.b')).resolves.toBeNull();
  });
  it('re-mints once the cached token has expired', async () => {
    let calls = 0;
    const login = async () => { calls += 1; return { t: `token-${calls}` }; };
    await resolveTokenRef('k6', login, 't', 0);
    await resolveTokenRef('k6', login, 't', 0);
    expect(calls).toBeGreaterThanOrEqual(1);
  });
  it('clearTokenRefCache forgets everything it minted', async () => {
    let calls = 0;
    const login = async () => { calls += 1; return { t: 'x' }; };
    await resolveTokenRef('k7', login, 't', 600);
    clearTokenRefCache();
    await resolveTokenRef('k7', login, 't', 600);
    expect(calls).toBe(2);
  });
});

describe('useIdempotencyKey', () => {
  it('holds one key across re-renders and rotates on demand', () => {
    let seen: { key: string; rotate: () => void } | null = null;
    const Probe = () => { seen = useIdempotencyKey(); return <Text>{seen.key}</Text>; };
    let tree!: renderer.ReactTestRenderer;
    act(() => { tree = renderer.create(<Probe />); });
    const first = seen!.key;
    act(() => { tree.update(<Probe />); });
    expect(seen!.key).toBe(first);
    act(() => seen!.rotate());
    act(() => { tree.update(<Probe />); });
    expect(seen!.key).not.toBe(first);
    act(() => tree.unmount());
  });
});
